import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CDU0sSpB.js";const h=JSON.parse('{"title":"Risks and Stop Conditions","description":"Hearth core risks, global and phase stop conditions, and product foundations that must not be removed.","frontmatter":{"title":"Risks and Stop Conditions","description":"Hearth core risks, global and phase stop conditions, and product foundations that must not be removed.","outline":[2]},"headers":[],"relativePath":"en/reference/risks.md","filePath":"en/reference/risks.md","lastUpdated":1793859143000}'),n={name:"en/reference/risks.md"};function i(s,e,d,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="risks-and-stop-conditions" tabindex="-1">Risks and Stop Conditions <a class="header-anchor" href="#risks-and-stop-conditions" aria-label="Permalink to &quot;Risks and Stop Conditions&quot;">​</a></h1><p class="lead">Knowing when to pause, roll back, or narrow the product is harder and more important than continuing to add features. These are signals that take priority when they appear. A phase may move more slowly, but it must not keep advancing while a risk remains unresolved.</p><h2 id="core-risks-and-stop-conditions" tabindex="-1">Core Risks and Stop Conditions <a class="header-anchor" href="#core-risks-and-stop-conditions" aria-label="Permalink to &quot;Core Risks and Stop Conditions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Early signal</th><th>Response</th></tr></thead><tbody><tr><td>Scope growth</td><td>Every phase adds executors while the core loop is unstable</td><td>Control scope with real task sets and phase exits</td></tr><tr><td>Unreliable recovery</td><td>Restarts lose tasks, sends repeat, or state disagrees</td><td>Single writer, checkpoints, idempotency, fault injection</td></tr><tr><td>Safety failure</td><td>Privilege escalation, credential leak, or successful prompt injection</td><td>Isolation, short-lived credentials, approval, denial tests</td></tr><tr><td>Cost blowout</td><td>High cost per task while human time does not fall</td><td>Hard budgets, context filtering, rules first, stop first</td></tr><tr><td>External executor dependency</td><td>An upgrade breaks many tasks</td><td>Version lock, adapters, degradation, human takeover</td></tr><tr><td>Maintenance overload</td><td>Most time goes to dependencies, channels, and environments</td><td>Do not rewrite the lower layers; reduce connectors; automate upgrade tests</td></tr><tr><td>Notification fatigue</td><td>Users disable notifications or ignore approvals</td><td>Attention budget, aggregation, quiet hours, reduced frequency</td></tr><tr><td>Wrong memory</td><td>Outdated, incorrect, or out-of-scope facts keep returning</td><td>Provenance, confidence, conflict handling, forgetting, user correction</td></tr><tr><td>Method drift</td><td>Procedures grow more complex and permissions expand</td><td>Evaluation, canary, permission intersection, rollback</td></tr><tr><td>Device divergence</td><td>Duplicate execution or a deleted item returns from an old device</td><td>One authoritative state, versions, deletion markers, device revocation</td></tr><tr><td>Product looks like a wrapper</td><td>No independent value remains without Codex</td><td>Task control, approval, recovery, memory, and evaluation must be owned</td></tr><tr><td>Trust erosion</td><td>Users cannot understand what happened or undo it</td><td>Explainable state, artifacts, receipts, stop switch</td></tr></tbody></table><p>Pause new feature work and fix the problem when any of these happens:</p><ul><li>A high-risk action exceeds its authority;</li><li>Credentials or sensitive data leak;</li><li>Fault injection produces a duplicate external effect;</li><li>Crash recovery falls below 95%;</li><li>Users cannot revoke a device, connection, or temporary authority;</li><li>Important memory cannot truly be forgotten;</li><li>Interface state disagrees with the fact record;</li><li>An external action cannot be reconciled;</li><li>Users do not know why they were interrupted or cannot stop proactive service.</li></ul><p>Each phase also has its own stop conditions. They are not &quot;did the code get written&quot;, but whether the user result promised by the phase is genuinely reliable.</p><table tabindex="0"><thead><tr><th>Phase</th><th>Do not advance if these remain</th></tr></thead><tbody><tr><td>Phase 1 · Minimum Complete MVP</td><td>Real tasks cannot be defined or completed; the browser cannot cover create, approve, recover, and retrieve; duplicate external actions cannot be removed</td></tr><tr><td>Phase 2 · Everyday Content Work</td><td>Users still repeat context; source authority cannot be narrowed; documents, tables, or web results cannot be verified; writes repeat or cannot be reconciled</td></tr><tr><td>Phase 3 · Desktop Operation</td><td>Success is low and takeover is unavailable; operation cannot prove it stayed in scope; failures leave half-finished high-risk state</td></tr><tr><td>Phase 4 · Proactive Service and Mobile Entry</td><td>Proactive reminders cause fatigue; users cannot predict interruption; phone approvals can be replayed; background work cannot stop</td></tr><tr><td>Phase 5 · Memory and Capability Evolution</td><td>Wrong memory keeps causing rework; forgetting does not propagate; evaluation can be gamed by sample selection; new methods expand authority</td></tr><tr><td>Phase 6 · Multi-device and Long-running Operation</td><td>Devices duplicate work or diverge; a lost device cannot be revoked; migration loses data; users cannot leave independently</td></tr></tbody></table><p>If Phase 2 ends without stable real everyday tasks, human time has not fallen, or maintenance keeps exceeding available time, narrow the product instead of adding features. A safety boundary below an acceptable level, refusal to trust Hearth with real data, or multi-device complexity that ruins single-device use are also signals to reduce scope.</p><h2 id="foundations-that-must-stay" tabindex="-1">Foundations That Must Stay <a class="header-anchor" href="#foundations-that-must-stay" aria-label="Permalink to &quot;Foundations That Must Stay&quot;">​</a></h2><ul><li>Rebuildable fact records and failure recovery;</li><li>Preview, approval, idempotency, and receipts for external actions;</li><li>Real tasks, failure samples, and independent verification;</li><li>Memory provenance, correction, and forgetting;</li><li>Low-interruption task cards and attention entries;</li><li>Pause and human takeover available at all times;</li><li>Permission boundaries, credential isolation, and a stop switch.</li></ul><p>These are not &quot;later&quot; features to cut when progress feels slow. They are preconditions for the product to exist, and no phase may trade them away.</p>',12)])])}const m=t(n,[["render",i]]);export{h as __pageData,m as default};
